def sequential_search(arr, element):
    """
    Returns a tuple (found, index).

    - found is True if the element exists in arr and False otherwise.
    - index is 0-based position of the element when found, or -1 if not found.
    """
    for i, val in enumerate(arr):
        if val == element:
            return (True, i)

    # Element not found after checking all items
    return (False, -1)


# Example usage and assertion from the problem statement
if __name__ == "__main__":
    assert sequential_search([11, 23, 58, 31, 56, 77, 43, 12, 65, 19], 31) == (True, 3)

# Additional test cases to verify correctness:
print(sequential_search([10, 20, 30], 20))   # (True, 1)
print(sequential_search([10, 20, 30], 5))    # (False, -1)

